class EndpointReadoutRepair(BaseHook):
    def on_run_start(self, ctx):
        self.ends = 0
        self.saved = []
        modules = dict(ctx.model.named_modules())
        selected = []
        for name, module in modules.items():
            if name.split('.')[-1] == 'layers' and isinstance(module, torch.nn.ModuleList):
                for block in list(module)[-2:]:
                    selected.extend(list(block.parameters()))
                parent = name.rsplit('.', 1)[0] if '.' in name else ''
                norm_name = parent + '.norm' if parent else 'norm'
                if norm_name in modules:
                    selected.extend(list(modules[norm_name].parameters()))
        with torch.no_grad():
            for parameter in selected:
                self.saved.append((parameter, parameter.detach().to(device='cpu', copy=True)))
            head = ctx.model.get_output_embeddings()
            self.output = head.weight.detach().to(device='cpu', copy=True)

    def on_domain_end(self, ctx, domain):
        self.ends += 1
        if self.ends != 2:
            return
        with torch.no_grad():
            for parameter, initial in self.saved:
                parameter.copy_(initial.to(device=parameter.device, dtype=parameter.dtype))
            head = ctx.model.get_output_embeddings()
            restored = self.output.to(device=head.weight.device, dtype=head.weight.dtype, copy=True)
            head.weight = torch.nn.Parameter(restored, requires_grad=False)

