class MatchedDistanceReadoutRestore(BaseHook):
    def on_run_start(self, ctx):
        self.domains = 0
        self.weights = list(ctx.model.named_parameters())
        indices = []
        for name, parameter in self.weights:
            parts = name.split('.')
            for i in range(len(parts) - 1):
                if parts[i] == 'layers' and parts[i + 1].isdigit():
                    indices.append(int(parts[i + 1]))
        self.last_layer = max(indices) if indices else -1
        self.restore = []
        self.base = []
        with torch.no_grad():
            for name, parameter in self.weights:
                parts = name.split('.')
                selected = False
                for i in range(len(parts) - 1):
                    if parts[i] == 'layers' and parts[i + 1].isdigit():
                        selected = int(parts[i + 1]) >= self.last_layer - 1
                if 'layers' not in parts and len(parts) > 1 and parts[-2] == 'norm':
                    selected = True
                self.restore.append(selected)
                self.base.append(parameter.detach().clone())

    def on_domain_start(self, ctx, domain):
        self.domains += 1

    def on_domain_end(self, ctx, domain):
        if self.domains != 2:
            return
        with torch.no_grad():
            device = self.weights[0][1].device
            total = torch.zeros((), device=device, dtype=torch.float64)
            remaining = torch.zeros_like(total)
            for entry, base, selected in zip(self.weights, self.base, self.restore):
                parameter = entry[1]
                flat = parameter.view(-1)
                initial = base.view(-1)
                for start in range(0, flat.numel(), 1048576):
                    end = min(start + 1048576, flat.numel())
                    delta = flat[start:end].float() - initial[start:end].float()
                    energy = delta.square().sum(dtype=torch.float64)
                    total.add_(energy)
                    if not selected:
                        remaining.add_(energy)
            if remaining.item() <= 0:
                return
            scale = torch.sqrt(total / remaining).item()
            for entry, base, selected in zip(self.weights, self.base, self.restore):
                parameter = entry[1]
                if selected:
                    parameter.copy_(base)
                else:
                    flat = parameter.view(-1)
                    initial = base.view(-1)
                    for start in range(0, flat.numel(), 1048576):
                        end = min(start + 1048576, flat.numel())
                        anchor = initial[start:end].float()
                        delta = flat[start:end].float() - anchor
                        flat[start:end].copy_(anchor + scale * delta)

