            return
        with torch.no_grad():
            for name, module in ctx.model.named_modules():
                leaf = name.split('.')[-1]
                if leaf == 'up_proj':
                    module.weight.mul_(2.0)
                    bias = getattr(module, 'bias', None)
                    if bias is not None:
                        bias.mul_(2.0)
                elif leaf == 'down_proj':
                    module.weight.mul_(0.5)

