class CodeSecantProjection(BaseHook):
    def on_run_start(self, ctx):
        self.domains = 0
        self.weights = [p for p in ctx.model.parameters() if p.requires_grad]
        with torch.no_grad():
            self.axes = [p.detach().clone() for p in self.weights]
        self.previous = []
        self.energy = []

    def on_domain_start(self, ctx, domain):
        self.domains += 1
        if self.domains != 2:
            return
        with torch.no_grad():
            for p, axis in zip(self.weights, self.axes):
                direction = p.float() - axis.float()
                norm = direction.square().sum().sqrt()
                if norm.item() > 0:
                    axis.copy_(direction / norm)
                else:
                    axis.zero_()
                self.energy.append(axis.float().square().sum().item())
                self.previous.append(p.detach().clone())

    def on_step_end(self, ctx, stats):
        if self.domains != 2:
            return
        with torch.no_grad():
            for p, previous, axis, energy in zip(self.weights, self.previous, self.axes, self.energy):
                if energy > 0:
                    increment = p.float() - previous.float()
                    original = increment.square().sum()
                    direction = axis.float()
                    coefficient = (increment * direction).sum() / energy
                    residual = increment - coefficient * direction
                    remaining = residual.square().sum()
                    if remaining.item() > 1e-20 and original.item() > 0:
                        residual.mul_(torch.sqrt(original / remaining))
                        p.copy_(previous.float() + residual)
                previous.copy_(p)

