class ProtectCodeNeurons(BaseHook):
    def on_run_start(self, ctx):
        self.domains = 0
        self.base = {}
        self.protected = []
        with torch.no_grad():
            for name, parameter in ctx.model.named_parameters():
                if name.endswith('down_proj.weight') and parameter.requires_grad:
                    self.base[name] = parameter.detach().clone()

    def on_domain_start(self, ctx, domain):
        self.domains += 1
        if self.domains != 2:
            return
        weights = dict(ctx.model.named_parameters())
        with torch.no_grad():
            for name, initial in self.base.items():
                parameter = weights[name]
                change = parameter.float() - initial.float()
                score = change.square().sum(dim=0)
                count = max(1, score.numel() // 4)
                indices = torch.topk(score, count).indices
                prefix = name[:-len('down_proj.weight')]
                for leaf, axis in (('down_proj.weight', 1), ('gate_proj.weight', 0), ('up_proj.weight', 0)):
                    key = prefix + leaf
                    if key in weights and weights[key].requires_grad:
                        target = weights[key]
                        anchor = target.index_select(axis, indices).detach().clone()
                        self.protected.append((target, axis, indices, anchor))
        self.base = {}

    def on_step_end(self, ctx, stats):
        if self.domains != 2:
            return
        with torch.no_grad():
            for parameter, axis, indices, anchor in self.protected:
                parameter.index_copy_(axis, indices, anchor)

